def src(*pairs):
    """src((P17, 'п. 5.2'), (P17, 'п. 3.3')) → 'stem|п. 5.2; stem|п. 3.3'"""
    return "; ".join(f"{d}|{p}" for d, p in pairs)


def dlg(*turns):
    """Диалог в формате платформы: чередование Пользователь/Ассистент, последняя реплика — пользователя."""
    names = ["Пользователь", "Ассистент"]
    return "\n".join(f"{names[i % 2]}: {t}" for i, t in enumerate(turns))


ROWS = []


def add(category, question, answer, sources="", notes=""):
    ROWS.append({"category": category, "question": question, "answer": answer, "sources": sources, "notes": notes})


